import csv
from collections import defaultdict

want = {
    "44d6581d-51ed-5650-ad74-1bd56a16c03e": "cool_sp",
    "3884ddd2-55e5-5e0a-9e6a-65822409bb01": "heat_sp",
    "75411709-a1c3-5621-904d-b03d146bc43d": "temp",
}

data = {k: {} for k in want.values()}
with open(VALUES_CSV) as f:
    rdr = csv.DictReader(f)
    for row in rdr:
        tsid = row["timeseries_id"]
        if tsid in want:
            t = row["timestamp"]
            if t.startswith("2018-01-27"):
                data[want[tsid]][t] = float(row["value"])

print("counts", {k: len(v) for k, v in data.items()})

all_ts = sorted(set(data["temp"]) | set(data["heat_sp"]) | set(data["cool_sp"]))
violations = []
for t in all_ts:
    temp = data["temp"].get(t)
    hi = data["cool_sp"].get(t)
    lo = data["heat_sp"].get(t)
    if temp is None or hi is None or lo is None:
        violations.append((t, "missing", temp, hi, lo))
        continue
    if temp > hi + 1e-9 or temp < lo - 1e-9:
        violations.append((t, temp, hi, lo))

print("total hours:", len(all_ts))
print("violations:", len(violations))
for v in violations[:20]:
    print(v)
